use super::misc::orient3d;
use crate::mesh::types::{ElementType, Mesh, Point};

pub(super) fn mesh_from_tets(nodes: Vec<Point>, elements: Vec<[usize; 4]>) -> Mesh {
    let mut mesh = Mesh::new(3);
    for p in &nodes {
        mesh.add_node(*p);
    }
    for elem_nodes in elements {
        let oriented = orient_mesh_tet_indices(&nodes, elem_nodes).unwrap_or(elem_nodes);
        mesh.add_element(ElementType::Tetrahedron, oriented.to_vec());
    }
    mesh.detect_boundaries();
    mesh
}

/// Orient materialized mesh tets according to `Mesh`'s positive signed-volume
/// convention.  The robust predicate uses the opposite determinant sign from
/// the FEM/Jacobian convention used by mesh validation, so this conversion is
/// deliberately separate from the recovery-orientation helper below.
pub(super) fn orient_mesh_tet_indices(points: &[Point], tet: [usize; 4]) -> Option<[usize; 4]> {
    let verts = [
        points[tet[0]],
        points[tet[1]],
        points[tet[2]],
        points[tet[3]],
    ];
    let predicate = orient3d(&verts);
    if predicate < 0.0 {
        Some(tet)
    } else if predicate > 0.0 {
        Some([tet[0], tet[2], tet[1], tet[3]])
    } else {
        None
    }
}

pub(super) fn orient_tet_indices(points: &[Point], tet: [usize; 4]) -> Option<[usize; 4]> {
    let verts = [
        points[tet[0]],
        points[tet[1]],
        points[tet[2]],
        points[tet[3]],
    ];
    let signed = orient3d(&verts);
    if signed > 0.0 {
        Some(tet)
    } else if signed < 0.0 {
        Some([tet[0], tet[2], tet[1], tet[3]])
    } else {
        None
    }
}
